from griffe import load
from griffe.extensions import Extension

class CheckedExtension(Extension):
    """Extension that appends [checked] to function docstrings."""

    def on_object_collected(self, obj):
        """Called when an object is collected during parsing."""
        if obj.is_function and obj.docstring is not None:
            obj.docstring.value += " [checked]"

# Aggregate extensions as griffe expects (list of Extension instances)
extensions = [CheckedExtension()]

# Load package through module-level entry point with extension enabled
package = load("mypkg", extensions=extensions)

# Display results
print(f"Package loaded: {package.name}")
for symbol_name, symbol_obj in package.members.items():
    if symbol_obj.is_function and symbol_obj.docstring:
        print(f"{symbol_name}: {symbol_obj.docstring.value}")
